  ui_story_30790101_149_dialog_content = "Nem vem com essa. Você quer mesmo que eu pague a taxa de dez Noitiuns por centímetro?",
  ui_story_30790101_150_dialog_content = "Não vejo porque não.",
  ui_story_30790101_151_dialog_content = "Me poupe.",
  ui_story_30790601_1_dialog_content = "PlayerName, finalmente te encontrei.",
  ui_story_30790601_2_dialog_content = "... Michenny? Não te reconheci com esse traje.",
  ui_story_30790601_3_dialog_content = "Na verdade, eu só queria consultar você sobre minha roupa. E vou compensá-lo pelo seu tempo.",
  ui_story_30790601_4_dialog_content = "Vestimenta? Compensação? Do que você está falando?",
  ui_story_30790601_5_dialog_content = "Eu planejei ir ao Deserto Rediesel e achei que esse traje me ajudaria a me misturar ao ambiente. O que você achou?",
  ui_story_30790601_6_dialog_content = "Eu ouvi você corretamente? Você vai ao Deserto Rediesel? Nobres de Lumo raramente vão lá.",
  ui_story_30790601_7_dialog_content = "Por favor, apenas responda minha pergunta—esse traje está bom?",
  ui_story_30790601_8_dialog_content = "Ah, é mais do que tudo bem, você está ótimo.",
  ui_story_30790601_9_dialog_content = "Obrigado, esta é sua recompensa por responder minha pergunta—100 Noitium.",
  ui_story_30790601_10_dialog_content = "Hã? Você quer me pagar só por responder uma pergunta? Não, obrigado.",
  ui_story_30790601_11_dialog_content = "Então você prefere uma joia? Infelizmente, o valor dessa questão não justifica uma joia.",
  ui_story_30790601_12_dialog_content = "Ah, não... esquece, vou ficar com o dinheiro, mas você também tem que responder uma pergunta para mim... por 100 Noitium.",
  ui_story_30790601_13_dialog_content = "Por que você está indo para o Deserto Rediesel?",
  ui_story_30790601_14_dialog_content = "Para este Dunecat.",
  ui_story_30790601_15_dialog_content = "Hã?",
  ui_story_30790601_16_dialog_content = "Miau.",
  ui_story_30790601_17_dialog_content = "O quê?! De onde veio o gato?",
  ui_story_30790601_18_dialog_content = "Eu mencionei isso aqui.",
  ui_story_30790601_19_dialog_content = "Desde quando você tem um gato de estimação?",
  ui_story_30790601_20_dialog_content = "Não é um animal de estimação.",
  ui_story_30790601_21_dialog_content = "Então, por que você tem isso?",
  ui_story_30790601_22_dialog_content = "Foi capturado por um traficante de animais no Deserto Rediesel, e sua cabeça foi ferida durante a captura.",
  ui_story_30790601_23_dialog_content = "O traficante levou-o para Lumópolis e vendeu-o para um nobre afetado que o abandonou à beira da estrada ao descobrir a lesão na cabeça.",
  ui_story_30790601_24_dialog_content = "Aconteceu de eu passar por ali e ver o que estava acontecendo, então prendi tanto o nobre quanto o traficante.",
  ui_story_30790601_25_dialog_content = "Esses malditos traficantes de animais!",
  ui_story_30790601_26_dialog_content = "Eu respondi quatro de suas perguntas no total.",
  ui_story_30790601_27_dialog_content = "T-Tudo bem, eu vou pagar, mas não tenho nenhum comigo agora. Vou te dar 100 Noitium primeiro, e o resto...",
  ui_story_30790601_28_dialog_content = "Não há necessidade, os padrões para essas coisas não são fixos e eu não me importo em flexibilizar as regras ao lidar com pessoas necessitadas como você. Apenas os 100 Noitium serão suficientes.",
  ui_story_30790601_29_dialog_content = "E-Empobrecido? Bom... Acho que você me pegou...",
  ui_story_30790601_30_dialog_content = "Miau...",
  ui_story_30790601_31_dialog_content = "Olhando os acessórios neste Dunecat, presumo que ele tenha um dono, alguém que deve estar muito ansioso agora.",
  ui_story_30790601_32_dialog_content = "Então, preciso enviá-lo de volta ao deserto o mais breve possível.",
  ui_story_30790601_33_dialog_content = "Eu irei com você. Você nunca esteve no Deserto Rediesel... É bastante perigoso lá.",
  ui_story_30790601_34_dialog_content = "Nesse caso... vou precisar fazer alguns cálculos.",
  ui_story_30790601_35_dialog_content = "De novo? Você até tirou a balança...",
  ui_story_30790601_36_dialog_content = "Taxa de escolta, despesas de viagem, despesas de segurança pessoal, despesas médicas e o valor agregado de ser o último Celestita no mundo...",
  ui_story_30790601_37_dialog_content = "O custo está um pouco alto demais. Deve ser fácil cobrir se for apenas uma perna quebrada, mas se você perder a vida...",
  ui_story_30790601_38_dialog_content = "Por que você acha que algo ruim vai acontecer comigo?!",
  ui_story_30790601_39_dialog_content = "Avaliadores devem considerar e medir todas as situações exatamente.",
  ui_story_30790601_40_dialog_content = "Apenas pense nisso como um amigo te acompanhando para fazer uma boa ação, sem custos ou perigo!",
  ui_story_30790601_41_dialog_content = "Dessa forma, preciso colocar a amizade em uma extremidade da balança. Isso é ainda mais pesado.",
  ui_story_30790601_42_dialog_content = "Não pense demais nas coisas. Com o tempo que levou para calcular tudo isso, já poderíamos ter levado este Dunecat para casa até agora.",
  ui_story_30790601_43_dialog_content = "De fato, esqueci de considerar as despesas de tempo agora mesmo. Obrigado pelo lembrete.",
  ui_story_30790601_44_dialog_content = "Tudo bem, tudo bem! Vamos nos apressar e partir logo.",
  ui_story_30790601_45_dialog_content = "Então, este é o Deserto Rediesel.",
  ui_story_30790601_46_dialog_content = "Sim. Você sabe onde fica a casa do Dunecat?",
  ui_story_30790601_47_dialog_content = "Não, eu não.",
  ui_story_30790601_48_dialog_content = "Então, como encontramos isso?",
  ui_story_30790601_49_dialog_content = "O Dunecat deveria saber.",
  ui_story_30790601_50_dialog_content = "Isso mesmo, muitos animais conseguem rastrear odores para encontrar o caminho de casa.",
  ui_story_30790601_51_dialog_content = "Uh, gatinho? Duney? Gato-Gato?",
  ui_story_30790601_52_dialog_content = "Zzzz... miau...",
  ui_story_30790601_53_dialog_content = "Michenny, como você chama esse gato, afinal?",
  ui_story_30790601_54_dialog_content = "Basta chamar de Dunecat.",
  ui_story_30790601_55_dialog_content = "Mas eu acabei de chamá-lo e ele me ignorou completamente... Talvez devêssemos dar um nome a ele.",
  ui_story_30790601_56_dialog_content = "Dar um nome seria como considerá-lo um animal de estimação. Nossa relação é simplesmente igual à de acompanhante mais acompanhado.",
  ui_story_30790601_57_dialog_content = "Tá bom. Eu pensei que você realmente gostava desse gato.",
  ui_story_30790601_58_dialog_content = "A noção de \"gostar\" pode facilmente levar à confusão. O julgamento não requer tais sentimentos.",
  ui_story_30790601_59_dialog_content = "Acho que o sol está me deixando tonto... e suas teorias só estão piorando a situação. Acho que vou desmaiar a qualquer momento.",
  ui_story_30790601_60_dialog_content = "Dunecat, você consegue encontrar sua casa?",
  ui_story_30790601_61_dialog_content = "Miau... Zzzz...",
  ui_story_30790601_62_dialog_content = "Ele rolou e voltou a dormir...",
  ui_story_30790601_63_dialog_content = "Os Dunecats são noturnos, o que significa que dormem durante o dia e são principalmente ativos à noite. Parece que precisaremos esperar até o anoitecer antes que ele possa nos levar até sua casa.",
  ui_story_30790601_64_dialog_content = "Eu tenho uma sugestão—podemos pedir ajuda ao Sinsa. Ele é o líder da Chave Rediesel.",
  ui_story_30790601_65_dialog_content = "Talvez eles possam nos ajudar a encontrar a casa do Dunecat, ou pelo menos nos fornecer comida e abrigo...",
  ui_story_30790601_66_dialog_content = "Não, como nobre, eu preferiria não lidar com esses bárbaros.",
  ui_story_30790601_67_dialog_content = "Você não os conhece - eles são realmente muito legais, e nós precisamos desesperadamente de comida e água agora.",
  ui_story_30790601_68_dialog_content = "Minha mãe me criou com treinamento de independência desde que eu era um bebê, e fui selecionado pela Corte de Justiça, entre os outros, por meu comportamento maduro e calmo.",
  ui_story_30790601_69_dialog_content = "Então, mesmo aqui no deserto, acredito que posso sobreviver sem a ajuda deles.",
  ui_story_30790601_70_dialog_content = "Tudo bem, se é esse o caso, o que você propõe que façamos agora?",
  ui_story_30790601_71_dialog_content = "Nossa primeira tarefa deve ser encontrar uma fonte de água. Devemos procurar um oásis ou cavar um poço nós mesmos.",
  ui_story_30790601_72_dialog_content = "Tudo que consigo ver por aqui é um mar interminável de dunas de areia. Não há sequer uma única árvore, muito menos o menor sinal de um oásis.",
  ui_story_30790601_73_dialog_content = "E como vamos cavar um poço sem ferramentas?",
  ui_story_30790601_74_dialog_content = "Vamos cavar com as mãos. Afinal, é só areia.",
  ui_story_30790601_75_option_content = "Tente cavar aqui",
  ui_story_30790601_76_dialog_content = "Não há nada aqui.",
  ui_story_30790601_77_option_content = "Tente cavar novamente",
  ui_story_30790601_78_dialog_content = "A areia desabou assim que comecei a cavar.",
  ui_story_30790601_79_option_content = "O plano falhou...",
  ui_story_30790601_80_dialog_content = "Não podemos simplesmente cavar às cegas assim e rezar por um milagre. Eu me lembro de ler algo sobre isso em um livro. Se você vê musgo no deserto, significa que há muita umidade por perto.",
  ui_story_30790601_81_dialog_content = "Apenas cavando nas áreas úmidas podemos ter uma chance de encontrar água subterrânea.",
  ui_story_30790601_82_dialog_content = "Tudo que consigo ver aqui são algumas plantas que parecem grama murcha—suas raízes devem conter um pouco de umidade. Vou tentar arrancar algumas.",
  ui_story_30790601_83_dialog_content = "Aqui, isso é para você.",
  ui_story_30790601_84_dialog_content = "Você tem certeza de que consegue comer essas raízes secas?",
  ui_story_30790601_85_dialog_content = "Claro, esta é uma planta do deserto. Ela deve conter água.",
  ui_story_30790601_86_option_content = "Dê uma mordida",
  ui_story_30790601_87_dialog_content = "Bah, está tudo arenoso.",
  ui_story_30790601_88_option_content = "O plano falhou...",
  ui_story_30790601_89_dialog_content = "Está ficando tarde. Se o Dunecat não acordar ou se a lesão na cabeça dele não estiver curada, talvez precisemos passar a noite aqui.",
  ui_story_30790601_90_dialog_content = "Então, devemos procurar pelo Pecado—",
  ui_story_30790601_91_dialog_content = "Devemos construir um abrigo simples, como uma pequena cabana de madeira.",
  ui_story_30790601_92_dialog_content = "Uma pequena cabana de madeira?! Sério?",
  ui_story_30790601_93_dialog_content = "Sim. Eu não sou um daqueles nobres sensíveis e irracionais—tudo que eu preciso é de uma simples cabana de madeira.",
  ui_story_30790601_94_dialog_content = "Certo—se o Matthieu estivesse aqui, ele provavelmente sugeriria que construíssemos uma casa dourada, enquanto você só quer que nós dois construamos uma cabana de madeira com nossas próprias mãos.",
  ui_story_30790601_95_dialog_content = "A única dificuldade aqui é que não há árvores grandes por perto.",
  ui_story_30790601_96_dialog_content = "Tem certeza de que essa é a ÚNICA dificuldade?",
  ui_story_30790601_97_option_content = "O plano falhou...",
  ui_story_30790601_98_dialog_content = "Tudo bem, você pode chamar alguém da Rediesel Wrench para ajudar. Eu vou pagar a eles.",
  ui_story_30790601_99_dialog_content = "Mas eles não podem contar a ninguém que eu os contratei. Isso será puramente um acordo empregador-empregado entre estranhos.",
  ui_story_30790601_100_dialog_content = "Como vou explicar algo assim para eles? Eles não aceitariam trabalho de um nobre tão arrogante. Vamos apenas esquecer isso.",
  ui_story_30790601_101_dialog_content = "Miau...",
  ui_story_30790601_102_dialog_content = "O gato finalmente acordou!",
  ui_story_30790601_103_dialog_content = "Se sentindo melhor, Dunecat? Consegue encontrar o caminho de casa agora?",
  ui_story_30790601_104_dialog_content = "Miau, miau...",
  ui_story_30790601_105_dialog_content = "Pode se mover devagar, mas não parece ter se recuperado totalmente ainda.",
  ui_story_30790601_106_dialog_content = "Então deixe seguir no seu próprio ritmo.",
  ui_story_30790601_107_dialog_content = "Seus olhos não saíram daquele gato por um segundo enquanto você soa completamente indiferente.",
  ui_story_30790601_108_dialog_content = "Bem, eu não gostaria que ele se perdesse novamente.",
  ui_story_30790601_109_dialog_content = "Argh! Ai, ai, ai!",
  ui_story_30790601_110_dialog_content = "É um escorpião! O bichinho está me beliscando e não solta!",
  ui_story_30790601_111_dialog_content = "O quê? O que eu faço? Eu-Eu vou te ajudar a tirar isso!",
  ui_story_30790601_112_dialog_content = "Não, não, não! Você vai arrancar minha pele! Argh! Suas pinças estão apertando ainda mais agora!",
  ui_story_30790601_113_dialog_content = "Miau!",
  ui_story_30790601_114_dialog_content = "Hã?! O Dunecat bateu no escorpião e ele simplesmente soltou e saiu correndo em um instante!",
  ui_story_30790601_115_dialog_content = "Está lambendo sua ferida, deve estar desinfetando-a.",
  ui_story_30790601_116_dialog_content = "*soluço* Você é o melhor gato do mundo! Você salvou minha vida!",
  ui_story_30790601_117_dialog_content = "...",
  ui_story_30790601_118_dialog_content = "Será que eu imaginei isso? Ele revirou os olhos para mim e depois virou-se e se afastou...",
  ui_story_30790601_119_dialog_content = "De fato, ele também não suporta você.",
  ui_story_30790601_120_dialog_content = "Vocês dois estão me dando exatamente o mesmo olhar agora...",
  ui_story_30790601_121_dialog_content = "<color=#e8d9bb>*estômago roncando*</color>",
  ui_story_30790601_122_dialog_content = "Que barulho foi esse?",
  ui_story_30790601_123_dialog_content = "Haha, você está com fome, ouvi seu estômago roncar. Mas eu também estou com fome.",
  ui_story_30790601_124_dialog_content = "O que é fome? Eu nunca passei fome na minha vida.",
  ui_story_30790601_125_dialog_content = "Seu estômago diz o contrário.",
  ui_story_30790601_126_dialog_content = "Não, sou um nobre elegante. Nunca fico com fome.",
  ui_story_30790601_127_dialog_content = "<color=#e8d9bb>*groooowwwwl*</color>",
  ui_story_30790601_128_dialog_content = "Está ainda mais alto...",
  ui_story_30790601_129_dialog_content = "Eu-Eu posso pegar.",
  ui_story_30790601_130_dialog_content = "Miau.",
  ui_story_30790601_131_dialog_content = "Hum? O gato pegou... um rato de campo? Ele colocou bem na sua frente, como se estivesse tentando te dar algo para comer.",
  ui_story_30790601_132_dialog_content = "Obrigado, Dunecat, mas eu realmente não consigo comer esse tipo de coisa.",
  ui_story_30790601_133_dialog_content = "Miau.",
  ui_story_30790601_134_dialog_content = "Miau.",
  ui_story_30790601_135_dialog_content = "Nossa! Lá! É outro Dunecat!",
  ui_story_30790601_136_dialog_content = "Eles são amigos? Mayserá que isso nos levará à casa deles? Eles estão caminhando um em direção ao outro!",
  ui_story_30790601_137_dialog_content = "Elas... hã? Elas apenas concordaram uma com a outra e seguiram caminhos diferentes?",
  ui_story_30790601_138_dialog_content = "Isso significa que eles não são família?",
  ui_story_30790601_139_dialog_content = "Esta é a natureza do Dunecat. Eles são caçadores solitários que não precisam de um grupo ou companheiros. Eles só ajudam e se comunicam uns com os outros quando necessário.",
  ui_story_30790601_140_dialog_content = "Sério... quanto mais eu vejo, mais parece que você e esses Dunecats são exatamente iguais.",
  ui_story_30790601_141_dialog_content = "Miau, miau, miau!!!",
  ui_story_30790601_142_dialog_content = "O que houve, Dunecat?",
  ui_story_30790601_143_dialog_content = "Por que está fazendo esse som? Todos os pelos dele estão arrepiados. Ele sente perigo?",
  ui_story_30790601_144_dialog_content = "Miau!!!",
  ui_story_30790601_145_dialog_content = "Seus olhos... O perigo está à espreita atrás de nós!",
  ui_story_30790601_146_dialog_content = "É uma cobra!",
  ui_story_30790601_147_dialog_content = "Não, é uma píton enorme! Ahhhhhh!",
  ui_story_30790601_148_dialog_content = "Não tenha medo, Dunecat! Pare de lutar! Eu não consigo segurar mais!",
  ui_story_30790601_149_dialog_content = "Está mostrando os dentes para a píton, como se estivesse tentando te proteger!",
  ui_story_30790601_150_dialog_content = "Aqui—pegue o Dunecat e corra! Vou segurar a píton!",
  ui_story_30790601_151_dialog_content = "Como eu poderia fugir e deixar você para trás? Vamos sair daqui juntos!",
  ui_story_30790601_152_dialog_content = "As cobras são inimigas naturais dos Dunegatos, então certamente vão atacar. Por favor, tire o gato daqui rapidamente! Só consigo segurar isso por tanto tempo!",
  ui_story_30790601_153_dialog_content = "Espere um segundo, estamos aqui conversando por tanto tempo e essa píton nem sequer nos atacou ainda.",
  ui_story_30790601_154_dialog_content = "Parece meio familiar.",
  ui_story_30790601_155_dialog_content = "Ah, é você, PlayerName.",
  ui_story_30790601_156_dialog_content = "Levar uma senhora encantadora a um lugar como este para um encontro no meio da noite, é realmente o seu estilo.",
  ui_story_30790601_157_dialog_content = "O quê? Quando foi que eu fiz algo remotamente parecido com isso?",
  ui_story_30790601_158_dialog_content = "Heheh. Estou brincando.",
  ui_story_30790601_159_dialog_content = "O que está fazendo aqui? A propósito, o python é o seu Palestrante, não é?",
  ui_story_30790601_160_dialog_content = "Eu estava apenas passando por aqui quando minha Píton Sagrada detectou algo incomum nas proximidades e vim verificar.",
  ui_story_30790601_161_dialog_content = "Eu nunca esperaria que isso te pegasse fazendo algo errado!",
  ui_story_30790601_162_dialog_content = "Não é assim. Estamos fazendo uma boa ação—ajudando este gato a encontrar sua casa.",
  ui_story_30790601_163_dialog_content = "Hmm, os enfeites neste pequeno gato são muito especiais. Eles pertencem a uma tribo no fundo do deserto.",
  ui_story_30790601_164_dialog_content = "Você sabe onde é a casa dele?",
  ui_story_30790601_165_dialog_content = "Sim. Essa tribo é terrivelmente misteriosa e tem muito pouco contato com o mundo exterior. Eles acreditam no Deus do Deserto e consideram o Dunecat como um mensageiro dos céus.",
  ui_story_30790601_166_dialog_content = "Eles escolhem o Dunecat mais bonito todos os anos e o enfeitam com ornamentos, considerando-o como seu totem e o símbolo sagrado da tribo.",
  ui_story_30790601_167_dialog_content = "Então é um gato muito importante. Você pode nos levar até a tribo dele?",
  ui_story_30790601_168_dialog_content = "Receio que não. Essa tribo é bastante hostil com estranhos. Como você encontrou esse Dunecat, afinal?",
  ui_story_30790601_169_dialog_content = "Michenny pegou o malfeitor que roubou este gato em Lumópolis.",
  ui_story_30790601_170_dialog_content = "Então, foi roubado. Nesse caso, você não pode ir diretamente à tribo, pois isso pode levar a um mal-entendido desagradável e desnecessário.",
  ui_story_30790601_171_dialog_content = "Vou levar o Dunecat de volta. Ainda tenho algumas conexões com eles, e acreditariam no que eu digo.",
  ui_story_30790601_172_dialog_content = "Isso parece uma ideia brilhante! O que você acha, Michenny?",
  ui_story_30790601_173_dialog_content = "Essa pessoa... Podemos realmente confiar nela com o gato?",
  ui_story_30790601_174_dialog_content = "Jeriah é um membro sênior da União Mensageira e também é minha amiga. Podemos confiar nela com certeza.",
  ui_story_30790601_175_dialog_content = "Que perspicaz de você! Você percebeu de cara que eu não sou confiável de jeito nenhum!",
  ui_story_30790601_176_dialog_content = "Não fique bravo, Jeriah. Michenny só está—",
  ui_story_30790601_177_dialog_content = "Tudo bem, acalme-se. Você deveria saber que eu não sou tão sensível assim.",
  ui_story_30790601_178_dialog_content = "... Tudo bem. Por favor, certifique-se de devolvê-lo em segurança. Eu vou te pagar.",
  ui_story_30790601_179_dialog_content = "Que garotinha encantadora. Embora esteja vestida para o deserto, ela fala como se estivesse em Lumópolis.",
  ui_story_30790601_180_dialog_content = "Já que você me confiou este trabalho, vamos considerá-lo um assunto oficial da União Mensageira.",
  ui_story_30790601_181_dialog_content = "Mas vou ter que deixar isso de lado por enquanto, até que eu tenha tempo para entregá-lo.",
  ui_story_30790601_182_dialog_content = "Parou! Esse gato está ferido! Ele precisa retornar para sua família imediatamente!",
  ui_story_30790601_183_dialog_content = "Vou te pagar mais... quanto você quiser.",
  ui_story_30790601_184_dialog_content = "Jeriah, eu sei que você normalmente não faz esse tipo de trabalho, mas esse negócio de gato é uma situação especial. Por favor...",
  ui_story_30790601_185_dialog_content = "Se for um pedido de um amigo, é claro que posso priorizá-lo. Se for um trabalho, no entanto...",
  ui_story_30790601_186_dialog_content = "P-Por favor, considere isso como um pedido de um amigo. Embora eu não saiba se você estaria disposto a me ver como um amigo...",
  ui_story_30790601_187_dialog_content = "Então a nobre senhora arrogante está disposta a abrir mão de seu status. Parece que você realmente se importa com este pequeno gato.",
  ui_story_30790601_188_dialog_content = "Por favor, Jeriah! Por favor, nos ajude a levar o gato para sua casa. Eu vou—",
  ui_story_30790601_189_option_content = "Vista uma saia!",
  ui_story_30790601_190_dialog_content = "Oh... Não acredito que você estaria disposto a ir tão longe...",
  ui_story_30790601_191_dialog_content = "Heheh, não tem como eu deixar passar uma oportunidade dessas.",
  ui_story_30790601_192_dialog_content = "O que eu disse agora?! Como eu pude falar algo assim...",
  ui_story_30790601_193_option_content = "Miau como um gato!",
  ui_story_30790601_194_dialog_content = "Deixe-me ouvir. Vamos ver se você é um linguista de gatinhos nato.",
  ui_story_30790601_195_dialog_content = "Miau... miau, miau... miau... Isso é vergonhoso...",
  ui_story_30790601_196_dialog_content = "Hehe, é bem fofo.",
  ui_story_30790601_197_dialog_content = "Isso foi terrivelmente constrangedor, PlayerName, mas tanto o gato quanto eu somos muito gratos a você.",
  ui_story_30790601_198_dialog_content = "Não é nada, tudo pelo gato... *soluço*",
  ui_story_30790601_199_dialog_content = "Tudo bem, vou trazer o gato de volta em segurança rapidamente.",
  ui_story_30790601_200_dialog_content = "Ótimo! Valeu!",
  ui_story_30790601_201_dialog_content = "Obrigada.",
  ui_story_30790601_202_dialog_content = "Então, Michenny, é hora de dizer adeus ao gatinho.",
  ui_story_30790601_203_dialog_content = "Por favor, deixe-me dar um último abraço.",
  ui_story_30790601_204_dialog_content = "Miaaau!",
  ui_story_30790601_205_dialog_content = "Kitty, espero que você se recupere logo. Vou sentir sua falta.",
  ui_story_30790601_206_dialog_content = "(Michenny segura o Dunecat em seus braços por muito tempo, recusando-se a soltar. Seus olhos brilham com o que parecem ser lágrimas.)",
  ui_story_30790601_207_dialog_content = "Michenny...",
  ui_story_30790601_208_dialog_content = "Tô bem.",
  ui_story_30790601_209_dialog_content = "Adeus, Dunecat.",
  ui_story_30790601_210_dialog_content = "Miau."
}
return config
